# These are modest, cache-friendly defaults for modern x64 CPUs.
# They can be tuned offline if desired without changing the C driver.
TI_E = 32  # tile size for i in phase E (E = A * B)
TJ_E = 32  # tile size for j in phase E
TK_E = 32  # tile size for k in phase E

TJ_F = 32  # tile size for j in phase F (F = C * D)
TL_F = 32  # tile size for l in phase F
TM_F = 32  # tile size for m in phase F

TI_G = 32  # tile size for i in phase G (G = E * F)
TL_G = 32  # tile size for l in phase G
TJ_G = 32  # tile size for j (reduction) in phase G


@proc
def kernel_3mm(
    ni: size,
    nj: size,
    nk: size,
    nl: size,
    nm: size,
    E: DATA_TYPE[ni, nj] @ DRAM,
    A: DATA_TYPE[ni, nk] @ DRAM,
    B: DATA_TYPE[nk, nj] @ DRAM,
    F: DATA_TYPE[nj, nl] @ DRAM,
    C: DATA_TYPE[nj, nm] @ DRAM,
    D: DATA_TYPE[nm, nl] @ DRAM,
    G: DATA_TYPE[ni, nl] @ DRAM,
):
    # ------------------------------------------------------------------
    # Phase 1: E := A * B
    #   E[ni, nj] = A[ni, nk] * B[nk, nj]
    # We first zero E, then accumulate A[i,k] * B[k,j] in a 3D blocked
    # fashion over (i, j, k) to improve locality.
    # ------------------------------------------------------------------

    # Initialize E to zero.
    for i in seq(0, ni):
        for j in seq(0, nj):
            E[i, j] = 0.0

    # 3D blocking over i, k, j:
    # Outer loops iterate over tiles, inner loops over points within tiles.
    # Loop order: I (rows) -> K (reduction) -> J (columns)
    # Inner order: i -> k -> j, with j innermost so that accesses to
    # B[k, j] and E[i, j] are unit-stride in j.
    for I in seq(0, (ni + TI_E - 1) / TI_E):
        for K in seq(0, (nk + TK_E - 1) / TK_E):
            for J in seq(0, (nj + TJ_E - 1) / TJ_E):
                for ii in seq(0, TI_E):
                    i = I * TI_E + ii
                    if i < ni:
                        for kk in seq(0, TK_E):
                            k = K * TK_E + kk
                            if k < nk:
                                # Cache A[i, k] in a scalar to reuse across the
                                # entire j-tile; this reduces reloads of A.
                                a_ik: DATA_TYPE
                                a_ik = A[i, k]
                                for jj in seq(0, TJ_E):
                                    j = J * TJ_E + jj
                                    if j < nj:
                                        E[i, j] += a_ik * B[k, j]

