    # Phase 2: F := C * D
    #   F[nj, nl] = C[nj, nm] * D[nm, nl]
    # Similar 3D blocking over (j, l, m). Loop order is chosen so that
    # the innermost loop runs over l, which is contiguous in row-major
    # F and D, and we reuse C[j, m] across that tile of l.
    # ------------------------------------------------------------------

    # Initialize F to zero.
    for j in seq(0, nj):
        for l in seq(0, nl):
            F[j, l] = 0.0

    # 3D blocking over j, m, l:
    # Tile loops: J (rows), M (reduction), L (columns)
    # Inner loops: j -> m -> l, with l innermost for unit-stride in l.
    for J in seq(0, (nj + TJ_F - 1) / TJ_F):
        for M in seq(0, (nm + TM_F - 1) / TM_F):
            for L in seq(0, (nl + TL_F - 1) / TL_F):
