                                    l = L * TL_F + ll
                                    if l < nl:
                                        F[j, l] += c_jm * D[m, l]

    # ------------------------------------------------------------------
    # Phase 3: G := E * F
    #   G[ni, nl] = E[ni, nj] * F[nj, nl]
    # We again zero G and then compute it using a blocked GEMM over
    # (i, l, j), strip-mining j as the reduction dimension.
    # The innermost loop runs over l, which is contiguous in row-major
    # G and F, and we reuse E[i, j] across each l-tile.
    # ------------------------------------------------------------------

    # Initialize G to zero.
    for i in seq(0, ni):
        for l in seq(0, nl):
            G[i, l] = 0.0

    # 3D blocking over i, j (reduction), l:
    # Tile loops: I (rows), J (reduction), L (columns)
    # Inner loops: i -> j -> l; j is the reduction dimension.
    for I in seq(0, (ni + TI_G - 1) / TI_G):
        for J in seq(0, (nj + TJ_G - 1) / TJ_G):
            for L in seq(0, (nl + TL_G - 1) / TL_G):
                for ii in seq(0, TI_G):
                    i = I * TI_G + ii
                    if i < ni:
                        for jj in seq(0, TJ_G):
                            j = J * TJ_G + jj
                            if j < nj:
                                # Reuse E[i, j] across a tile of l.
                                e_ij: DATA_TYPE
                                e_ij = E[i, j]
                                for ll in seq(0, TL_G):
                                    l = L * TL_G + ll
                                    if l < nl:
                                        G[i, l] += e_ij * F[j, l]
EXO END
