    # Phase 1: E := A * B
    #
    # Original form:
    #   for i in 0..ni:
    #     for j in 0..nj:
    #       E[i, j] = 0
    #       for k in 0..nk:
    #         E[i, j] += A[i, k] * B[k, j]
    #
    # Here we compute E tile-by-tile. For each (I, J) tile we:
    #   1. Zero the entire E-tile once.
    #   2. Accumulate contributions from all K-tiles:
    #        E[i, j] += sum_{k in tile} A[i, k] * B[k, j]
    # This preserves E[i, j] = sum_k A[i, k] * B[k, j] while greatly
    # improving cache locality for A, B, and E.
    # ------------------------------------------------------------------
    for I in seq(0, (ni + TI - 1) / TI):
        for J in seq(0, (nj + TJ - 1) / TJ):
            # Zero the current E tile [I, J].
            for ii in seq(0, TI):
                i: size = I * TI + ii
                if i < ni:
                    for jj in seq(0, TJ):
                        j: size = J * TJ + jj
                        if j < nj:
                            E[i, j] = 0.0

            # Accumulate contributions from all K-tiles.
            for K in seq(0, (nk + TK - 1) / TK):
                for ii in seq(0, TI):
                    i: size = I * TI + ii
                    if i < ni:
                        for kk in seq(0, TK):
                            k: size = K * TK + kk
                            if k < nk:
