# These can be tuned per target machine.
TILE_I_E = 32
TILE_J_E = 32
TILE_K_E = 32

TILE_J_F = 32
TILE_L_F = 32
TILE_M_F = 32

TILE_I_G = 32
TILE_L_G = 32
TILE_J_G = 32


