    # Phase 2: F := C * D
    #   F[j, l] = sum_m C[j, m] * D[m, l]
    #
    # We tile over (j, l, m):
    #   - J tiles rows of C and F
    #   - L tiles columns of D and F
    #   - M tiles the reduction dimension over m
    #
    # The l loop (within each tile) is innermost so that F and D are
    # accessed with unit stride.
