from exo.API_scheduling import *  # imported for completeness
from exo.libs.memories import DRAM

# Cache-/vector-friendly tile sizes.
# These are compile-time constants so that loop bounds remain affine.
TI = 32  # tile size along i / row dimensions
TJ = 32  # tile size along j (shared inner dimension)
TK = 32  # tile size along k (A*B reduction)
TL = 32  # tile size along l / column dimensions
TM = 32  # tile size along m (C*D reduction)


@proc
def kernel_3mm(
    ni: size,
    nj: size,
    nk: size,
    nl: size,
    nm: size,
    E: DATA_TYPE[ni, nj] @ DRAM,
    A: DATA_TYPE[ni, nk] @ DRAM,
    B: DATA_TYPE[nk, nj] @ DRAM,
    F: DATA_TYPE[nj, nl] @ DRAM,
    C: DATA_TYPE[nj, nm] @ DRAM,
    D: DATA_TYPE[nm, nl] @ DRAM,
    G: DATA_TYPE[ni, nl] @ DRAM,
):
    # ------------------------------------------------------------------
    # Phase 1: E := A * B
    #   A ∈ R^{ni×nk}, B ∈ R^{nk×nj}, E ∈ R^{ni×nj}
    #   E[i, j] = sum_k A[i, k] * B[k, j]
    #
    # Tiled GEMM over (i, j, k) to improve cache locality. Within each
    # (I, J) tile of E we:
    #   - zero the tile once,
    #   - then accumulate contributions from all k-tiles.
    # The innermost loop iterates over j so that B[k, j] and E[i, j] are
    # accessed with unit stride (row-major).
    # ------------------------------------------------------------------
    for I in seq(0, (ni + TI - 1) / TI):
        for J in seq(0, (nj + TJ - 1) / TJ):
            # Zero the current E tile [I, J].
            for ii in seq(0, TI):
                if I * TI + ii < ni:
                    for jj in seq(0, TJ):
                        if J * TJ + jj < nj:
                            E[I * TI + ii, J * TJ + jj] = 0.0
            # Accumulate contributions from tiles of A and B along k.
            for K in seq(0, (nk + TK - 1) / TK):
                for ii in seq(0, TI):
                    if I * TI + ii < ni:
                        for kk in seq(0, TK):
                            if K * TK + kk < nk:
                                a_val: DATA_TYPE
                                a_val = A[I * TI + ii, K * TK + kk]
                                for jj in seq(0, TJ):
                                    if J * TJ + jj < nj:
                                        E[I * TI + ii, J * TJ + jj] = \
                                            E[I * TI + ii, J * TJ + jj] + \
                                            a_val * B[K * TK + kk, J * TJ + jj]

    # ------------------------------------------------------------------
    # Phase 2: F := C * D
    #   C ∈ R^{nj×nm}, D ∈ R^{nm×nl}, F ∈ R^{nj×nl}
    #   F[j, l] = sum_m C[j, m] * D[m, l]
    #
    # Tiled GEMM over (j, l, m). The innermost loop iterates over l so
    # that accesses to D[m, l] and F[j, l] are unit-stride (row-major).
    # ------------------------------------------------------------------
    for J in seq(0, (nj + TJ - 1) / TJ):
        for L in seq(0, (nl + TL - 1) / TL):
            # Zero the current F tile [J, L].
            for jj in seq(0, TJ):
                if J * TJ + jj < nj:
                    for ll in seq(0, TL):
                        if L * TL + ll < nl:
                            F[J * TJ + jj, L * TL + ll] = 0.0
