            for M in seq(0, (nm + TM - 1) / TM):
                for jj in seq(0, TJ):
                    if J * TJ + jj < nj:
                        for mm in seq(0, TM):
                            if M * TM + mm < nm:
                                c_val: DATA_TYPE
                                c_val = C[J * TJ + jj, M * TM + mm]
                                for ll in seq(0, TL):
                                    if L * TL + ll < nl:
